export const GUIDE_FAQS = [
  { question: "Can Charlie run experiments and work toward goals for me?", answer: "Use the experiment and customer-draft actions your workspace shows. Tell Charlie what to run or which decision to apply, and it starts without a confirmation card. Research contacts nobody. Asking for research or a goal does not authorize sending, publishing or spending money elsewhere. Ask separately when you want those actions. Work you did not ask for does not start on its own." },
  { question: "Is anything sent without my approval?", answer: "Drafting does not send. Review your recipients and messages, then tell Charlie to send. Your approved drafts send from connected Gmail without another confirmation. If you ask to automate your emails, you authorize automatic first emails and follow-ups within your saved limits. You can pause sending or stop automating in chat. Community and social drafts are for you to copy and post yourself." },
  { question: "How many emails can go out each day?", answer: "15 a day is recommended and is your default limit, including follow-ups. It is not a fixed maximum. Ask Charlie for a higher daily limit, up to 100. Your requested change applies directly. Your connected Gmail has one daily limit across ventures you own. Every email keeps your sender address, explains where you found the recipient's address or that you imported the contact, and includes the opt-out line. Contacts blocked from outreach, including anyone who opted out or is not eligible, are not emailed. Follow-ups stop when someone replies." },
  { question: "Where do the leads come from?", answer: "Supymem looks at public posts, communities and websites for people who fit your venture. Reachable leads include contact details published on their own website or public profiles, with source links. Emails are not guessed. A lead may fit your audience without showing a public sign of the problem; that distinction is marked." },
  { question: "What happens when you reach your usage limit?", answer: "You see a plain notice when you reach your limit. Choose Buy more in Settings and use the purchase or request option available to your account, then retry. Your saved work is kept." },
  { question: "Is my data shared?", answer: "Your venture keeps its conversation and saved work in its workspace. Do not put passwords or provider keys in chat; use dedicated connection or settings controls. Connecting Gmail requires signing in with the provider and approving access. Publishing makes your landing page public. For questions about who can access particular data, use Report a problem in Account settings before adding sensitive information." },
  { question: "Can I stop or pause?", answer: "Yes. Say “pause sending” or “stop automating” and review the control Charlie shows. Venture settings also offers pause and resume. Local tasks have their own stop controls. Check the final status before starting again." },
  { question: "Do I need the Mac app?", answer: "Not for supported web flows such as research, landing pages and customer drafts. A connected Mac is needed for local browser tasks. LinkedIn profiles can be found in the background without a Mac when search is available, or through your own browser on your connected Mac. The Mac installer is a beta flow that requires a valid invitation code." },
  { question: "What is computer use?", answer: "It is a short browser task that runs on your Mac. Give Charlie a goal and the exact websites to use. Give Charlie the complete task and the sites you want it to use. Your requested task starts when the required Mac permissions and connections are ready. Keep the Mac app open and follow the task's device instructions. Controlling other Mac apps is not available yet." },
  { question: "Why did a search find only a few people?", answer: "Supymem needs public evidence and a usable public contact route. A narrow audience or missing public contact details can limit the results. Read the sources and the search's recovery advice. Try a broader audience or add a contact you know, with a source and a reason you may contact them. A small result is not proof that demand is absent." },
  { question: "How do I publish my page or take it down?", answer: "Review your private preview and choose the part of the address before .supymem.com. Enable and test the waitlist if you use it. Ask Charlie to publish your landing page when you want it live. To take it down, ask to unpublish. Your request runs without another confirmation. Closing the waitlist alone does not take the page down." },
  { question: "Does Supymem send LinkedIn messages for me?", answer: "No. Supymem never sends LinkedIn messages for you. Profile search can return exact LinkedIn links, connection notes and follow-up drafts through background search when available or your connected Mac. You copy them, open LinkedIn and send each message yourself." },
  { question: "Where do I find results, and how long will it take?", answer: "Research, plans, previews, email drafts and status come back in chat. Ask Charlie to show them again. Replies arrive in your Gmail. Charlie tells you in chat, and you answer from Gmail. The times in this guide are rough estimates of your reading and review time, not run deadlines. Searches and builds vary, and customer replies can take days." },
] as const;

export function guidePromptById(id: string | null): string | undefined {
  return [...GUIDE_QUICK_START, ...GUIDE_USE_CASES, ...GUIDE_TIPS].find(item => item.id === id)?.prompt;
}

