export function guideContent(local = false): {
  capabilities: readonly GuideCapability[];
  quickStart: readonly (GuideCapability | typeof GUIDE_QUICK_START[number])[];
  useCases: typeof GUIDE_USE_CASES;
  tips: typeof GUIDE_TIPS;
  faqs: readonly { question: string; answer: string; settingsLink?: GuideSettingsLink }[];
} {
  return local
    ? { capabilities: LOCAL_GUIDE_CAPABILITIES, quickStart: LOCAL_QUICK_START, useCases: [], tips: [], faqs: LOCAL_FAQS }
    : { capabilities: GUIDE_CAPABILITIES, quickStart: GUIDE_QUICK_START, useCases: GUIDE_USE_CASES, tips: GUIDE_TIPS, faqs: GUIDE_FAQS };
}

export function guideBlockedMessage(card: GuideCapability, capabilities: readonly { name: string; state: string; next_step: string }[]): string | undefined {
  for (const name of card.requires || []) {
    const item = capabilities.find(value => value.name === name);
    if (!item || item.state !== "ready") return item?.next_step.trim()
      || "Your feature status could not be loaded. Open Settings > Capabilities and choose Try again, then return here to request your work.";
  }
  return undefined;
}

export function filterGuideCapabilities(query: string, topic: GuideTopic, stage: GuideStage, local = false): readonly GuideCapability[] {
  const terms = query.trim().toLocaleLowerCase().split(/\s+/).filter(Boolean);
  return guideContent(local).capabilities.filter(card =>
    (topic === "All topics" || card.topic === topic) &&
    (stage === "Any stage" || card.stages.includes(stage)) &&
    terms.every(term => [card.title, card.topic, card.description, card.result, card.note, card.prompt].join(" ").toLocaleLowerCase().includes(term)));
}

export function guideDestinationHref(destination: GuideDestination, ventureId?: string, local = false): string {
  if (destination === "coding-tools") return "/settings/local#coding-tools";
  if (destination === "local-models") return "/settings/local#providers-title";
  if (destination === "data") return "/settings/local#your-data-title";
  if (local && ["settings", "account", "download"].includes(destination)) return "/settings/local";
  if (local && destination === "browser-tasks") return "/connections";
  if (destination === "new") return "/new";
  if (destination === "ventures") return "/";
  if (destination === "account" || destination === "download") return `/${destination}`;
  if (destination === "connections") return ventureId ? `/connections?venture=${encodeURIComponent(ventureId)}` : "/connections";
  if (destination === "gtm") return ventureId ? `/gtm?venture=${encodeURIComponent(ventureId)}` : "/gtm";
  if (!ventureId) return "/";
  const base = `/v/${encodeURIComponent(ventureId)}`;
  if (destination === "browser-tasks") return `${base}/settings#settings-computer-use`;
  return destination === "overview" ? base : `${base}/${destination}`;
}
